<template><section class="skill-picker"><label>只读技能 <select :value="selected" :disabled="busy || loading" @change="choose($event)"><option value="">不使用技能</option><option v-for="item in skills" :key="item.id" :value="item.id">{{ item.title }}</option></select></label><small>仅影响之后的新普通 AI 回答</small><p v-if="error" role="alert">技能设置未确认，请重试 <button type="button" @click="reset">刷新</button></p></section></template>
<script>
import api from '../apis/module/readonlySkills';
export default {name:'ReadonlySkillPicker',props:{conversationId:{type:String,required:true},identity:{type:String,required:true}},data:()=>({skills:[],selected:'',busy:false,loading:false,error:false,epoch:0,controller:null,pending:null}),computed:{scope(){return JSON.stringify([this.identity,this.conversationId]);}},watch:{scope:{flush:'sync',handler:'reset'}},mounted(){this.reset();},beforeUnmount(){this.epoch++;this.controller?.abort();},methods:{
 async reset(){this.epoch++;this.controller?.abort();this.skills=[];this.selected='';this.busy=false;this.error=false;this.pending=null;if(!this.conversationId||!this.identity)return;const version=this.epoch,controller=new AbortController();this.controller=controller;this.loading=true;try{const [catalog,current]=await Promise.all([api.list(controller.signal),api.get(this.conversationId,controller.signal)]);if(version!==this.epoch||controller.signal.aborted)return;if(!Array.isArray(catalog?.items)||catalog.items.some(x=>typeof x.id!=='string'||x.version!==1||typeof x.title!=='string'||x.source_policy!=='distinguish_user_material_tool_and_inference'||!Array.isArray(x.allowed_tools)||x.allowed_tools.some(t=>!['read_conversation_history','read_conversation_evidence'].includes(t))))throw new Error('INVALID_SKILLS');this.skills=catalog.items;const selection=current?.selection;if(selection!==null&&(!selection||selection.version!==1||!this.skills.some(x=>x.id===selection.id)))throw new Error('INVALID_SKILL_SELECTION');this.selected=selection?.id||'';}catch(e){if(version===this.epoch&&!controller.signal.aborted){this.error=true;controller.abort();}}finally{if(version===this.epoch)this.loading=false;}},
 async choose(event){const id=event.target.value;event.target.value=this.selected;if(this.busy||this.loading||!this.skills.some(x=>x.id===id)&&id!=='')return;const version=this.epoch,controller=new AbortController();this.controller=controller;this.busy=true;this.error=false;const signature=id||'';if(!this.pending||this.pending.signature!==signature)this.pending={signature,client_request_id:crypto.randomUUID()};const body={client_request_id:this.pending.client_request_id,skill_id:id||null,version:id?1:null};try{const result=await api.set(this.conversationId,body,controller.signal);if(version!==this.epoch||controller.signal.aborted)return;const selection=result?.selection;if(id ? selection?.id!==id||selection?.version!==1 : selection!==null)throw new Error('INVALID_SKILL_SELECTION');this.selected=id;this.pending=null;}catch(e){if(version===this.epoch&&!controller.signal.aborted)this.error=true;}finally{if(version===this.epoch)this.busy=false;}}
}};
</script>
<style scoped>.skill-picker{font-size:var(--admin-font-base);color:#365e43}.skill-picker select{margin:0 6px;border:1px solid #d6e7dc;border-radius:5px;padding:3px;color:#365e43;background:white}.skill-picker small{color:#718579}.skill-picker p{color:#a54236;margin:4px 0}</style>
